import javax.jms.*;
import org.apache.activemq.ActiveMQConnectionFactory;

public class JmsProducerExample {
    public static void main(String[] args) throws JMSException {
        ConnectionFactory connectionFactory = new ActiveMQConnectionFactory("tcp://localhost:61616");
        Connection connection = connectionFactory.createConnection();
        connection.start();

        Session session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        Destination destination = session.createQueue("PAYMENT.PROCESSING.QUEUE");

        MessageProducer producer = session.createProducer(destination);
        TextMessage message = session.createTextMessage("Payload: Order #10849");

        producer.send(message);
        System.out.println("Successfully sent message to JMS broker.");

        producer.close();
        session.close();
        connection.close();
    }
}
